<?php
declare(strict_types=1);
namespace App\Services\Classrooms;
use App\Models\{Classroom,LegacyClassroomMapping,Student,User};
class ClassroomLegacyMappingService { public function labels(int $year){$mapped=LegacyClassroomMapping::where('academic_year_id',$year)->pluck('id','legacy_label');return Student::whereNotNull('classroom_label')->where('classroom_label','!=','')->selectRaw('classroom_label, count(*) total')->groupBy('classroom_label')->get()->map(fn($x)=>['label'=>$x->classroom_label,'total'=>$x->total,'mapped'=>$mapped->has($x->classroom_label),'suggestion'=>$this->suggest($x->classroom_label,$year)]);}
 public function suggest(string $label,int $year):?Classroom{$normal=fn($v)=>str($v)->lower()->replaceMatches('/[^a-z0-9]+/','')->toString();return Classroom::where('academic_year_id',$year)->with('gradeLevel')->get()->first(fn($c)=>$normal($c->display_name)===$normal($label)||$normal($c->code)===$normal($label));}
 public function preview(int $year,string $label,Classroom $room):array{$students=Student::where('classroom_label',$label)->get();$ready=$students->filter(fn($s)=>$s->status==='active'&&!$s->classroomMemberships()->where('academic_year_id',$year)->where('status','active')->exists());return ['label'=>$label,'room'=>$room,'total'=>$students->count(),'ready'=>$ready->count(),'skipped'=>$students->count()-$ready->count()];}
 public function map(User $actor,int $year,string $label,Classroom $room,ClassroomMembershipService $members):array{$mapping=LegacyClassroomMapping::firstOrCreate(['academic_year_id'=>$year,'legacy_label'=>$label],['classroom_id'=>$room->id]);if($mapping->mapped_at)return ['added'=>0,'errors'=>['Data kelas lama ini sudah dipetakan.']];$ids=Student::where('classroom_label',$label)->pluck('id')->all();$result=$members->addMany($actor,$room,$ids);$mapping->update(['classroom_id'=>$room->id,'mapped_students_count'=>$result['added'],'mapped_by'=>$actor->id,'mapped_at'=>now()]);activity('kelas-rombel')->causedBy($actor)->performedOn($mapping)->log("Memetakan {$result['added']} siswa dari data kelas lama ke {$room->display_name}.");return $result;}}
